import { notFound } from "next/navigation";
import { requireVendorStorePage } from "@/lib/vendor-area";
import { prisma } from "@/lib/prisma";
import VendorSection from "@/components/vendor-section";
import { PasswordChangeForm } from "@/components/password-change-form";
import { VendorPageHeader } from "@/components/vendor-page-header";
const titles:Record<string,string>={orders:"Sifarişlər",returns:"Qaytarılma müraciətləri",inventory:"Anbar qalığı",products:"Məhsullarım",imports:"Məhsulları toplu əlavə et",campaigns:"Kampaniyalar",sales:"Satış və gəlir",profile:"Mağazam",reviews:"Müştəri rəyləri",notifications:"Bildirişlər",subscription:"Abunəliyim",settings:"Hesab və parametrlər"};
export default async function Section({params}:{params:Promise<{storeId:string;section:string}>}){const {storeId,section}=await params;if(section==="security"){const access=await requireVendorStorePage(storeId);if(!access)notFound();const account=await prisma.user.findUnique({where:{id:access.user.id},select:{passwordAuthEnabled:true}});return <div className="mx-auto max-w-3xl"><VendorPageHeader eyebrow="Hesab təhlükəsizliyi" title="Şifrəni dəyiş" description="Şifrə hesabınız üçündür və sahib olduğunuz bütün mağazalara girişdə istifadə olunur."/><section className="mt-5 rounded-card border border-line bg-white p-5 sm:p-8">{account?.passwordAuthEnabled?<PasswordChangeForm/>:<p className="text-sm text-fg-secondary">Bu hesab Google ilə idarə olunur; BAGATI şifrəsi dəyişdirilmir.</p>}<p className="mt-6 text-xs leading-5 text-fg-muted">Şifrənizi unutmusunuzsa, <a className="font-medium text-primary underline" href="/forgot-password">bərpa keçidi istəyin</a>. Çoxmərhələli təsdiq hazırda təqdim edilmir.</p></section></div>}if(!titles[section])notFound();if(!await requireVendorStorePage(storeId))notFound();return <VendorSection storeId={storeId} section={section} title={titles[section]}/>}
